 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    objects = []
    # The signal sources are monochrome 3x3 blocks.
    seen = set()
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0 or (r, c, color) in seen:
                continue
            if all(grid[y][x] == color for y in range(r, r + 3) for x in range(c, c + 3)):
                objects.append((r + 1, c + 1, color))
                seen.add((r, c, color))
    signals = {}
    for r, c, color in objects:
        for x in range(w):
            signals.setdefault((r, x), set()).add(color)
        for y in range(h):
            signals.setdefault((y, c), set()).add(color)
    out = [row[:] for row in grid]
    for (r, c), colors in signals.items():
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out
